data.content:
@exists_bound_subsingleton_hModule_one_curve : ∀ {k : Type u_1} [inst : Field k] (C : Over (Spec (CommRingCat.of k)))
  [IsProper C.hom] [inst_2 : SmoothOfRelativeDimension 1 C.hom] [inst_3 : GeometricallyIrreducible C.hom],
  ∃ b, ∀ (D : C.left.CurveDivisor), b ≤ Scheme.CurveDivisor.deg k D → Subsingleton ((Scheme.divisorSheaf k D).HModule 1)
@exists_bound_h0_eq_genus_curve : ∀ {k : Type u_1} [inst : Field k] (C : Over (Spec (CommRingCat.of k)))
  [inst_1 : IsProper C.hom] [inst_2 : SmoothOfRelativeDimension 1 C.hom] [inst_3 : GeometricallyIrreducible C.hom],
  ∃ b,
    ∀ (D : C.left.CurveDivisor),
      b ≤ Scheme.CurveDivisor.deg k D → ↑(Scheme.divisorSheaf k D).h0 = 1 - ↑(genus C) + Scheme.CurveDivisor.deg k D
@exists_isFinite_isDominant_toP1 : ∀ {k : Type u_1} [inst : Field k] {C : Over (Spec (CommRingCat.of k))}
  [SmoothOfRelativeDimension 1 C.hom] [IsProper C.hom] [GeometricallyIrreducible C.hom],
  ∃ π, IsFinite π ∧ IsDominant π ∧ π ≫ P1.structureMap k = C.hom
